CREATE TABLE cmdb_ire_field_provenance_history (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY, tenant_id BIGINT UNSIGNED NOT NULL, ci_id BIGINT UNSIGNED NOT NULL, field_key VARCHAR(80) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, source_id BIGINT UNSIGNED NOT NULL, run_type VARCHAR(24) NOT NULL, run_id BIGINT UNSIGNED NULL, rule_version BIGINT UNSIGNED NOT NULL DEFAULT 0, source_priority SMALLINT UNSIGNED NOT NULL DEFAULT 100, observed_at DATETIME(6) NOT NULL, accepted_at DATETIME(6) NOT NULL, value_hash BINARY(32) NOT NULL, archived_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), KEY cmdb_ire_prov_history_ci(tenant_id,ci_id,field_key,id), KEY cmdb_ire_prov_history_run(tenant_id,run_type,run_id), CONSTRAINT cmdb_ire_prov_history_ci FOREIGN KEY(tenant_id,ci_id) REFERENCES cmdb_cis(tenant_id,id), CONSTRAINT cmdb_ire_prov_history_source FOREIGN KEY(tenant_id,source_id) REFERENCES cmdb_ire_sources(tenant_id,id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
